'use strict';
const $=id=>document.getElementById(id);
const categories=['Games','Finance','Shopping','Casino','Sports','Social Networking','Utilities','Entertainment'];
let data=null,visible=[];
function toast(text){$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,3500)}
function selectLeads(d,category,query){if(!d.complete||d.is_baseline)return [];const q=query.trim().toLowerCase();return d.leads.map(a=>({...a,charts:a.charts.filter(c=>d.coverage[c.category]?.ready&&(!category||c.category===category))})).filter(a=>a.charts.length&&`${a.name} ${a.developer}`.toLowerCase().includes(q))}
function cell(text){const t=document.createElement('td');t.textContent=text;return t}
function render(){if(!data)return;const cat=$('category').value,q=$('search').value;visible=selectLeads(data,cat,q);const selected=cat?[cat]:categories;const ready=selected.filter(c=>data.coverage[c]?.ready).length;
$('count').textContent=`${visible.length} matching ${visible.length===1?'app':'apps'} · Deduplicated across all 8 categories`;
const body=$('body');body.replaceChildren();
for(const a of visible){const tr=document.createElement('tr');tr.append(cell(a.charts.map(c=>'#'+c.rank).join(' / ')));const name=document.createElement('td'),strong=document.createElement('strong'),dev=document.createElement('div');strong.textContent=a.name;dev.className='developer';dev.textContent=a.developer;name.append(strong,dev);tr.append(name,cell(a.charts.map(c=>c.category).join(' / ')));const status=document.createElement('td'),badge=document.createElement('span');badge.className='badge fresh';badge.textContent='New entrant';status.append(badge);tr.append(status);const link=document.createElement('a');link.href=`https://apps.apple.com/us/app/id${encodeURIComponent(a.id)}`;link.target='_blank';link.rel='noopener noreferrer';link.textContent='App Store ↗';link.setAttribute('aria-label',`View ${a.name} on the App Store`);const td=document.createElement('td');td.append(link);tr.append(td);body.append(tr)}
$('empty').hidden=visible.length>0;$('export').disabled=visible.length===0;
if(!visible.length){const empty=$('empty');empty.querySelector('h2').textContent=!data.complete?'Collection incomplete':data.is_baseline?'Baseline saved':q.trim()?'No matching apps':'No 30-day entrants today';empty.querySelector('p').textContent=!data.complete?'All eight charts must be collected before publishing a daily list. Missing data is not a zero-result day.':data.is_baseline?'Today’s apps form the starting list. Tomorrow, apps absent from today’s charts can qualify.':q.trim()?'Try another app name, developer, or category.':'Every matching app appeared in at least one monitored category during the previous 30 days.'}
}
$('category').onchange=render;$('search').oninput=render;
$('share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);toast('Link copied')}catch{toast('Copy the URL from your browser’s address bar to share')}};
$('export').onclick=()=>{const safe=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const rows=[['Snapshot date','App','Developer','Qualifying categories and ranks','App Store'],...visible.map(a=>[data.date,a.name,a.developer,a.charts.map(c=>`${c.category} #${c.rank}`).join('; '),`https://apps.apple.com/us/app/id${a.id}`])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`app-radar-new-entrants-${data.date}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
fetch('data.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('load');return r.json()}).then(d=>{data=d;for(const category of categories){const opt=document.createElement('option');opt.value=category;opt.textContent=category;$('category').append(opt)}$('date').textContent=`Snapshot: ${d.date} · Europe/Rome`;
const available=categories.filter(c=>d.coverage[c]?.current_available).length;$('rows').textContent=`${available} / 8`;$('new').textContent=d.complete&&!d.is_baseline?selectLeads(d,'','').length:'—';$('tracking-window').firstChild.textContent=d.window_days;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
$('notice').textContent=today!==d.date?`Showing the ${d.date} snapshot. Today's update is not available.`:!d.complete?'Collection failed or is incomplete. No daily list is available.':d.is_baseline?'Baseline saved. Tomorrow’s list will compare against today; earlier unrecorded days count as no appearance.':`Compared with ${d.history_days} recorded day(s) in the previous 30-day window; ${d.unrecorded_history_days} earlier day(s) count as no appearance.`;if(d.incomplete_history_dates.length)$('notice').textContent+=` ${d.incomplete_history_dates.length} recorded day(s) were incomplete; successfully observed App IDs still count.`;render()}).catch(()=>{$('notice').textContent='Unable to load the snapshot. Please refresh to try again.';$('date').textContent='Snapshot unavailable';$('empty').hidden=false;$('empty').querySelector('h2').textContent='Data temporarily unavailable';$('empty').querySelector('p').textContent='Please try again later.'});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_app_charts',title:'Filter new chart entrants',description:'Filter confirmed new entrants, update the page, and return the match count and first ten results.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['',...categories]},query:{type:'string'}},required:['category','query'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!data)throw Error('Snapshot not loaded');if(!input||!['',...categories].includes(input.category)||typeof input.query!=='string')throw Error('Invalid filters');$('category').value=input.category;$('search').value=input.query;render();return{date:data.date,count:visible.length,results:visible.slice(0,10)}}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
